def capitalize_string(value): """Capitalizes the first letter of a string, this is useful.""" return value.capitalize()
def reverse_string(value): """Reverses the given string.""" return value[::-1]
def count_vowels(value: str): """Counts the number of vowels in a string. For example, 'hello' has 2 vowels.""" return sum(1 for char in value.lower() if char in 'aeiou')
def is_palindrome(value): """Checks if a word is a palindrome.""" return value == value[::-1]
def convert_to_uppercase(value): """Converts a string to uppercase""" return value.upper()
